              "value": "={{ $json.body.executionId || $execution.id }}",
              "type": "string"
            },
            {
              "id": "norm-optimized",
              "name": "optimizedPrompt",
              "value": "={{ $json.body.optimizedPrompt || '' }}",
              "type": "string"
            }
          ]
        },
        "options": {}
      },
      "type": "n8n-nodes-base.set",
      "typeVersion": 3.4,
      "position": [-400, 0],
      "id": "normalize-input-001",
      "name": "Normalize Input"
    },
    {
      "parameters": {
        "model": {
          "__rl": true,
          "value": "gpt-4o-mini",
          "mode": "list",
          "cachedResultName": "gpt-4o-mini"
        },
        "builtInTools": {},
        "options": {
          "temperature": 0.5
        }
      },
      "type": "@n8n/n8n-nodes-langchain.lmChatOpenAi",
      "typeVersion": 1.3,
      "position": [-160, 200],
      "id": "openai-model-summarizer",
      "name": "OpenAI Chat Model",
      "credentials": {
        "openAiApi": {
          "id": "REPLACE_WITH_CREDENTIAL_ID",
          "name": "OpenAI account"
        }
      }
    },
    {
      "parameters": {
        "promptType": "define",
        "text": "=System: You are a social media strategist with expertise in content adaptation.\n\nUser: Analyze this website/article content and create a summary that:\n1. Captures the 3 most important insights\n2. Includes actionable advice or tips when present\n3. Maintains the original tone and perspective\n4. Highlights implications for the target audience\n5. Stays under 250 words for social media adaptation\n\nWebsite URL: {{ $json.websiteUrl }}\nUser context: {{ $json.userPrompt }}\n\nContent:\n{{ $json.scrapedContent }}",
        "batching": {}
      },
      "type": "@n8n/n8n-nodes-langchain.chainLlm",
      "typeVersion": 1.9,
      "position": [-160, 0],
      "id": "article-summarizer-001",
      "name": "Article Summarizer"
    },
    {
      "parameters": {
        "jsCode": "const platform = ($('Normalize Input').first().json.platform || 'linkedin').toLowerCase();\nconst userPrompt = $('Normalize Input').first().json.userPrompt || '';\nconst optimized = $('Normalize Input').first().json.optimizedPrompt || '';\n\nconst specs = {\n  linkedin: {\n    name: 'LinkedIn',\n    maxWords: 300,\n    style: 'Professional, insightful, structured paragraphs. Include a clear call to action. No meta commentary—output only paste-ready post text.',\n    hashtags: '3-5 relevant hashtags at the end'\n  },\n  twitter: {\n    name: 'X (Twitter)',\n    maxWords: 50,\n    style: 'Punchy, sharp, conversational. Under 280 characters total. End with a question or CTA. Output only paste-ready tweet text.',\n    hashtags: '1-2 hashtags max'\n  },\n  x: {\n    name: 'X (Twitter)',\n    maxWords: 50,\n    style: 'Punchy, sharp, conversational. Under 280 characters total.',\n    hashtags: '1-2 hashtags max'\n  },\n  instagram: {\n    name: 'Instagram',\n    maxWords: 150,\n    style: 'Visual storytelling tone, emoji-friendly, line breaks for readability. Hook in first line.',\n    hashtags: '10-15 hashtags in a separate block at end'\n  },\n  facebook: {\n    name: 'Facebook',\n    maxWords: 200,\n    style: 'Friendly, community-focused, conversational. Encourage comments and shares.',\n    hashtags: '2-4 hashtags'\n  },\n  reddit: {\n    name: 'Reddit',\n    maxWords: 400,\n    style: 'Authentic, value-first, no salesy tone. Title + body format. Markdown-friendly.',\n    hashtags: 'No hashtags'\n  },\n  medium: {\n    name: 'Medium',\n    maxWords: 500,\n    style: 'Thoughtful long-form intro/teaser. Compelling headline + subtitle + opening paragraphs.',\n    hashtags: 'Tags as comma-separated at end'\n  },\n  devto: {\n    name: 'Dev.to',\n    maxWords: 400,\n    style: 'Developer-focused, technical but accessible. Include code-friendly formatting hints if relevant.',\n    hashtags: '4 tags for Dev.to'\n  },\n  threads: {\n    name: 'Threads',\n    maxWords: 100,\n    style: 'Casual, concise, conversational micro-post.',\n    hashtags: '2-3 hashtags'\n  },\n  youtube: {\n    name: 'YouTube Community',\n    maxWords: 150,\n    style: 'Engaging community post, ask a question, tease video topic if relevant.',\n    hashtags: 'Minimal'\n  },\n  producthunt: {\n    name: 'Product Hunt',\n    maxWords: 200,\n    style: 'Launch-style: problem, solution, unique value. Exciting but credible.',\n    hashtags: 'None'\n  }\n};\n\nconst spec = specs[platform] || specs.linkedin;\nconst base = optimized || userPrompt;\n\nconst systemPrompt = `You are an expert ${spec.name} content creator.`;\nconst userMessage = `${base}\\n\\nPlatform: ${spec.name}\\nStyle: ${spec.style}\\nMax length: ~${spec.maxWords} words\\nHashtags: ${spec.hashtags}\\n\\nArticle summary:\\n{{ summary }}\\n\\nWebsite: {{ url }}\\n\\nRules:\\n- Output ONLY the final post content ready to copy-paste\\n- No preamble like \"Here is your post\"\\n- Match ${spec.name} best practices`;\n\nreturn [{\n  json: {\n    platform,\n    platformName: spec.name,\n    systemPrompt,\n    userMessageTemplate: userMessage,\n    websiteUrl: $('Normalize Input').first().json.websiteUrl,\n    userId: $('Normalize Input').first().json.userId,\n    executionId: $('Normalize Input').first().json.executionId\n  }\n}];"
      },
      "type": "n8n-nodes-base.code",
      "typeVersion": 2,
      "position": [80, 0],
      "id": "platform-prompt-builder",
      "name": "Platform Prompt Builder"
    },
    {
      "parameters": {
        "model": {
          "__rl": true,
          "value": "gpt-4o-mini",
          "mode": "list",
          "cachedResultName": "gpt-4o-mini"
        },
        "builtInTools": {},
        "options": {
          "temperature": 0.7
        }
      },
      "type": "@n8n/n8n-nodes-langchain.lmChatOpenAi",
      "typeVersion": 1.3,
      "position": [320, 200],
      "id": "openai-model-generator",
      "name": "OpenAI Chat Model1"
    },
    {
      "parameters": {
        "promptType": "define",
        "text": "={{ $('Platform Prompt Builder').item.json.systemPrompt }}\n\n{{ $('Platform Prompt Builder').item.json.userMessageTemplate.replace('{{ summary }}', $json.text).replace('{{ url }}', $('Platform Prompt Builder').item.json.websiteUrl) }}",
        "batching": {}
      },
      "type": "@n8n/n8n-nodes-langchain.chainLlm",
      "typeVersion": 1.9,
      "position": [320, 0],
      "id": "platform-content-generator",
      "name": "Generate Platform Post"
    },
    {
      "parameters": {
        "jsCode": "const summary = $('Article Summarizer').first().json.text || '';\nconst generated = $('Generate Platform Post').first().json.text || '';\nconst meta = $('Platform Prompt Builder').first().json;\nconst input = $('Normalize Input').first().json;\n\nconst wordCount = generated.split(/\\s+/).filter(Boolean).length;\nconst qualityScore = Math.min(100, Math.round(\n  (generated.length > 50 ? 40 : 0) +\n  (wordCount >= 20 ? 30 : wordCount * 1.5) +\n  (summary.length > 100 ? 30 : 15)\n));\n\nreturn [{\n  json: {\n    success: true,\n    executionId: input.executionId,\n    userId: input.userId,\n    platform: meta.platform,\n    platformName: meta.platformName,\n    websiteUrl: input.websiteUrl,\n    summary,\n    content: generated,\n    qualityScore,\n    wordCount,\n    generatedAt: new Date().toISOString()\n  }\n}];"
      },
      "type": "n8n-nodes-base.code",
      "typeVersion": 2,
      "position": [560, 0],
      "id": "format-response-001",
      "name": "Format API Response"
    },
    {
      "parameters": {
        "respondWith": "json",
        "responseBody": "={{ $json }}",
        "options": {
          "responseCode": 200
        }
      },
      "type": "n8n-nodes-base.respondToWebhook",
      "typeVersion": 1.1,
      "position": [800, 0],
      "id": "respond-webhook-001",
      "name": "Respond to Webhook"
    },
    {
      "parameters": {
        "respondWith": "json",
        "responseBody": "={\"success\": false, \"error\": \"Workflow processing failed\", \"executionId\": \"{{ $execution.id }}\"}",
        "options": {
          "responseCode": 500
        }
      },
      "type": "n8n-nodes-base.respondToWebhook",
      "typeVersion": 1.1,
      "position": [800, 200],
      "id": "respond-error-001",
      "name": "Respond Error"
    }
